"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["26481"],{29223(e){e.exports=JSON.parse('{"id":"F522","slug":"kelly-criterion","name":"Kelly Criterion","subject":"Decision-Making, Risk & Model Limitations","section":"Decision quality","topic":"Decision quality","level":"Intermediate","aliases":["bet sizing","optimal fraction","position sizing","growth optimal","half Kelly"],"formula":{"latex":"f^{*}=p-\\\\frac{1-p}{b},\\\\quad g(f)=p\\\\ln(1+bf)+(1-p)\\\\ln(1-f)","also":[],"text":"Best fraction of capital to stake = p - (1 - p) / b, where p is the chance of winning and b is the net payoff per 1 staked; Growth rate = p x ln(1 + b x f) + (1 - p) x ln(1 - f)"},"symbols":[{"symbol":"p","meaning":"Probability of winning","unit":"percent"},{"symbol":"b","meaning":"Net odds: profit per 1 staked if you win (you lose the 1 otherwise)","unit":"number"},{"symbol":"f*","meaning":"Fraction of capital that maximizes long-run growth","unit":"percent"},{"symbol":"g","meaning":"Expected log growth per bet","unit":"percent"}],"when_to_use":"Use it to size repeated bets when you think you have an edge. Betting more than Kelly lowers long-run growth and raises the risk of ruin; betting twice Kelly gives zero growth. Because the win probability is only an estimate, most practitioners use half Kelly or less. A zero or negative answer means there is no edge and the right stake is zero.","worked_example":{"problem":"A trade wins 55% of the time. A win pays 1 for each 1 staked and a loss costs the 1 staked.","inputs":{"p":55,"b":1},"steps":[{"label":"Kelly fraction = p - (1 - p) / b","working":"0.55-(1-0.55) / 1","value":"10.00%"},{"label":"Growth per bet at Kelly","working":"0.55 x ln(1+1 x 0.1)+(1-0.55) x ln(1-0.1)","value":"0.501%"},{"label":"Half Kelly","working":"0.1 / 2","value":"5.00%"},{"label":"Growth per bet at half Kelly","working":"0.55 x ln(1+1 x 0.05)+(1-0.55) x ln(1-0.05)","value":"0.375%"},{"label":"Share of Kelly growth kept by half Kelly","working":"0.00375261 / 0.00500837","value":"74.9%"},{"label":"Double Kelly","working":"2 x 0.1","value":"20.00%"},{"label":"Growth per bet at double Kelly","working":"0.55 x ln(1+1 x 0.2)+(1-0.55) x ln(1-0.2)","value":"-0.014%"}],"answer":"The Kelly fraction is 10.00%, so stake 10.00% of capital each time. That gives expected growth of 0.501% per bet. Half Kelly (5.00%) gives 0.375%, which is 74.9% of the growth with much smaller swings. Betting 20.00% (double) gives -0.014%, no growth at all."},"calculator":{"available":true,"inputs":[{"id":"p","label":"Probability of winning","unit":"%","type":"number","default":55,"hint":""},{"id":"b","label":"Net payoff per 1 staked","unit":"","type":"number","default":1,"hint":"","min":0.01}],"checks":[{"expr":"p>0 and p<1","message":"Enter a win probability between 0 and 100%."}],"steps":[{"id":"f","label":"Kelly fraction = p - (1 - p) / b","expr":"p-(1-p)/b","format":"pct2"},{"id":"g","label":"Growth per bet at Kelly","expr":"p*ln(1+b*f)+(1-p)*ln(1-f)","format":"pct3"},{"id":"fh","label":"Half Kelly","expr":"f/2","format":"pct2"},{"id":"gh","label":"Growth per bet at half Kelly","expr":"p*ln(1+b*fh)+(1-p)*ln(1-fh)","format":"pct3"},{"id":"share","label":"Share of Kelly growth kept by half Kelly","expr":"gh/g","format":"pct1"},{"id":"f2","label":"Double Kelly","expr":"2*f","format":"pct2"},{"id":"g2","label":"Growth per bet at double Kelly","expr":"p*ln(1+b*f2)+(1-p)*ln(1-f2)","format":"pct3"}],"results":["f","g","gh","g2"],"percent_inputs_typed_as_whole_numbers":true,"tested_against":{"f":0.10000000000000009,"g":5.008366846356839e-3,"fh":5.0000000000000044e-2,"gh":3.752607818789871e-3,"share":0.7492677621088347,"f2":0.20000000000000018,"g2":-1.3774185471934763e-4}},"finder":{"finds":"How much of your capital to put on a bet with an edge","needs":"Win probability and payoff"},"related":[{"slug":"pairs-trade-sizing","name":"Pairs Trade Sizing and Reversion Profit"},{"slug":"expected-value","name":"Expected Value"},{"slug":"evpi","name":"Expected Value of Perfect Information"}],"related_ids":["F415","F058","F521"],"group":"Risk and quantitative methods","mathml":"<span class=\\"katex\\"><math xmlns=\\"http://www.w3.org/1998/Math/MathML\\" display=\\"block\\"><semantics><mrow><msup><mi>f</mi><mo lspace=\\"0em\\" rspace=\\"0em\\">\u2217</mo></msup><mo>=</mo><mi>p</mi><mo>\u2212</mo><mfrac><mrow><mn>1</mn><mo>\u2212</mo><mi>p</mi></mrow><mi>b</mi></mfrac><mo separator=\\"true\\">,</mo><mspace width=\\"1em\\"/><mi>g</mi><mo stretchy=\\"false\\">(</mo><mi>f</mi><mo stretchy=\\"false\\">)</mo><mo>=</mo><mi>p</mi><mi>ln</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>+</mo><mi>b</mi><mi>f</mi><mo stretchy=\\"false\\">)</mo><mo>+</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>p</mi><mo stretchy=\\"false\\">)</mo><mi>ln</mi><mo>\u2061</mo><mo stretchy=\\"false\\">(</mo><mn>1</mn><mo>\u2212</mo><mi>f</mi><mo stretchy=\\"false\\">)</mo></mrow><annotation encoding=\\"application/x-tex\\">f^{*}=p-\\\\frac{1-p}{b},\\\\quad g(f)=p\\\\ln(1+bf)+(1-p)\\\\ln(1-f)</annotation></semantics></math></span>","alsoMathml":[],"prev":{"slug":"justified-price-to-book","name":"Justified Price-to-Book Ratio (Banks)"},"next":{"slug":"autocorrelation","name":"Lag-1 Autocorrelation"},"lesson":null,"total":522}')}}]);